from taf.gnb.oam.coam.cu.schemas.internal.emservice.search_parameters_of_current_plan import SearchParametersEMSERVICE

from taf.gnb.oam.coam.cu.interfaces.cuoam25r3 import CUOAM25R3
from taf.gnb.oam.coam.cu.utilities.logger import log_warning

from taf.gnb.oam.coam.cu.schemas.internal.cp_config.cu_reset_response_v1 import CuResetCPCONFIGV1

from taf.gnb.oam.coam.cu.services.licensed.agent.agent_licensed_v1 import AGENTLicensedv1

from taf.gnb.oam.coam.cu.schemas.internal.asm.plan_activation_response_v1 import PlanActivationASMV1

from taf.gnb.oam.coam.cu.services.internal.sec.sec_v1 import SECv1

from taf.gnb.oam.coam.cu.exception import ApiException


class CUOAM26R1(CUOAM25R3):
    def __init__(self, con_details):
        super(CUOAM26R1, self).__init__(con_details)
        self.agent_licensed = AGENTLicensedv1(con_details=con_details)
        self.sec_v1 = SECv1(con_details=con_details)

    def search_parameters_of_current_plan(self, parameter_name, raw=False, **kwargs):
        search_parameter_response = self.emservice_v1.search_parameters_of_current_plan(parameter_name=parameter_name,
                                                                                        **kwargs)
        if raw:
            return search_parameter_response

        else:
            formatted_response = SearchParametersEMSERVICE.from_object_dict(search_parameter_response)
            return self._format_parameter_to_fit_asm_response(formatted_response)

    def get_measurement_info(self, measurement_id):
        try:
            return self.pm.get_measurement_info(measurement_id=measurement_id)

        except ApiException as e:
            if "No API found with those values API" in e.body:
                raise NotImplementedError("Endpoint used by this keyword has been removed and is no longer usable")

            else:
                raise e

    def get_counter_info(self, counter_id, measurement_id):
        try:
            return self.pm.get_counter_info(counter_id=counter_id, measurement_id=measurement_id)

        except ApiException as e:
            if "No API found with those values API" in e.body:
                if measurement_id:
                    log_warning("Using PMv2 endpoint /api/pm/v2/counters/{counter_id}/info as PMv1 is no longer available, "
                                "argument measurement_id you gave will not be used.")

                return self.pm_v2.get_counter_info(counter_id=counter_id)

            else:
                raise e

    def reset_cu(self, timeout, use_m2m=True, raw=False):
        """
        Manages CU reset requests by adapting to the ongoing transition of M2M and internal endpoints from CP-CONFIG.

        As of 26R1, M2M endpoints for CU reset have migrated to OAM-AGENT, and internal CP-CONFIG endpoints are
        scheduled for mid-release removal. For internal this method prioritizes CP-CONFIG requests and, if unsuccessful,
        uses OAM-AGENT.
        """
        if use_m2m:
            return self.agent_licensed.reset_cu(timeout=timeout)

        else:
            try:
                response = self.cp_config.reset_cu(timeout=timeout)
                return response if raw else CuResetCPCONFIGV1.from_object_dict(response)

            except ApiException as e:
                if "No API found with those values API" in e.body:
                    return self.agent.reset_cu(timeout=timeout)

                else:
                    raise e

    def plan_activation(self, plan_id, timeout, pre_activated=False, raw=False, **kwargs):
        if pre_activated:
            return self.em_service_licensed_v1.plan_activation(plan_id=plan_id, timeout=timeout)

        else:
            response = self.asm_v1.plan_activation(plan_id=plan_id, timeout=timeout)
            return response if raw else PlanActivationASMV1.from_object_dict(response)

    def get_operation_state_of_activating_plan(self, plan_id, operation_id, pre_activated, raw=False):
        if pre_activated:
            return self.em_service_licensed_v1.get_operation_state_of_activating_plan(plan_id=plan_id,
                                                                                      operation_id=operation_id)

        else:
            response = self.asm_v1.get_operation_state_of_activating_plan(plan_id=plan_id, operation_id=operation_id)
            return response if raw else PlanActivationASMV1.from_object_dict(response)

    def trigger_download_of_current_plan(self, include_auto_config_data=True, include_runtime_data=False, timeout=30,
                                         use_m2m=True):
        if use_m2m:
            return self.cm_licensed.download_current_plan(include_auto_config_data=include_auto_config_data,
                                                          include_runtime_data=include_runtime_data,
                                                          timeout=timeout)

        else:
            return self.cm.download_current_plan(include_auto_config_data=include_auto_config_data,
                                                 include_runtime_data=include_runtime_data,
                                                 timeout=timeout)

    def get_status_of_current_plan_download(self, operation_id, timeout=30, use_m2m=True):
        if use_m2m:
            return self.cm_licensed.get_download_plan_operation_status(operation_id=operation_id, timeout=timeout)

        else:
            return self.cm.get_download_plan_operation_status(operation_id=operation_id, timeout=timeout)

    def save_downloaded_plan_to_local(self, operation_id, path, timeout=30, use_m2m=True):
        if use_m2m:
            self.cm_licensed.get_downloaded_plan_file(operation_id=operation_id, path=path, timeout=timeout)

        else:
            self.cm.get_downloaded_plan_file(operation_id=operation_id, path=path, timeout=timeout)

    def check_secret_mode(self, timeout=30):
        return self.sec_v1.get_token_info(timeout=timeout)["UnpublishedDataMode"]
